(function(){function el(tag,className,text){var e=document.createElement(tag);if(className)e.className=className;if(text!=null)e.textContent=text;return e}function friendlyError(res){return res&&res.error||"Something went wrong. Please try again."}function fmtWhen(dateStr,timeStr){try{var d=new Date(dateStr+"T"+timeStr+":00");if(isNaN(d.getTime()))return dateStr+" "+timeStr;return d.toLocaleString(undefined,{weekday:"short",month:"short",day:"numeric",hour:"numeric",minute:"2-digit"})}catch(e){return dateStr+" "+timeStr}}function statusLabel(m){switch(m.status){case"REQUESTED":return"Requested";case"RINGING":return"Ringing…";case"ACCEPTED":return m.meetFailed?"Setup failed":"Setting up…";case"READY":return"Ready to join";case"DECLINED":return"Declined";case"CANCELLED":return"Cancelled";case"ENDED":return"Ended";case"MISSED":return"No answer";default:return m.status}}function defaultMeetingDateTime(){var d=new Date;d.setDate(d.getDate()+1);var hour=Math.max(9,Math.min(18,(new Date).getHours()+1));d.setHours(hour,0,0,0);var pad=function(n){return String(n).padStart(2,"0")};return{date:d.getFullYear()+"-"+pad(d.getMonth()+1)+"-"+pad(d.getDate()),time:pad(d.getHours())+":00"}}function todayDateStr(){var d=new Date;var pad=function(n){return String(n).padStart(2,"0")};return d.getFullYear()+"-"+pad(d.getMonth()+1)+"-"+pad(d.getDate())}function validateDraft(purpose,date,time){if(!purpose)return"Please say what the meeting is about.";if(!date||!time)return"Please choose a date and time.";var when=new Date(date+"T"+time+":00");if(isNaN(when.getTime()))return"Please provide a valid date and time.";if(when.getTime()<Date.now()-5*60*1e3)return"That time has already passed.";return null}function mount(container,ctx){var meetings=[];var busyMeetingId=null;container.innerHTML="";var list=el("div","meeting-list");var formWrap=el("div","meeting-request-wrap");container.appendChild(list);container.appendChild(formWrap);function hasActiveCall(){return meetings.some(function(m){return m.status==="RINGING"||m.status==="ACCEPTED"||m.status==="READY"})}function renderTrigger(){formWrap.innerHTML="";if(!ctx.canRequest()){if(ctx.signInHint){var hint=el("p","meeting-request-signin-hint");var hintLink=document.createElement("a");hintLink.href=ctx.signInHint.href;hintLink.textContent=ctx.signInHint.label;hint.appendChild(hintLink);hint.appendChild(document.createTextNode(ctx.signInHint.after));formWrap.appendChild(hint)}return}var row=el("div","meeting-trigger-row");if(!hasActiveCall()){var callBtn=el("button","btn btn-primary","Video Call Now");callBtn.type="button";callBtn.addEventListener("click",startCallNow);row.appendChild(callBtn)}var btn=el("button","btn meeting-request-trigger","Request Meeting");btn.type="button";btn.addEventListener("click",function(){formWrap.innerHTML="";formWrap.appendChild(renderForm())});row.appendChild(btn);formWrap.appendChild(row)}function startCallNow(){return Api.post("startVideoCallNow",ctx.params()).then(function(res){if(!res.ok){alert(friendlyError(res));return}var idx=meetings.findIndex(function(m){return m.meetingId===res.meeting.meetingId});if(idx===-1)meetings.push(res.meeting);else meetings[idx]=res.meeting;render()})}function renderForm(){var form=el("form","meeting-request-form");form.appendChild(el("label","meeting-request-label","Purpose"));var purpose=document.createElement("textarea");purpose.className="meeting-request-input";purpose.placeholder="What is this meeting about?";purpose.maxLength=500;form.appendChild(purpose);form.appendChild(el("label","meeting-request-label","Notes (optional)"));var notes=document.createElement("textarea");notes.className="meeting-request-input";notes.placeholder="Anything else to add?";notes.maxLength=1e3;form.appendChild(notes);var row=el("div","meeting-request-datetime-row");var dateField=el("div","meeting-request-datetime-field");dateField.appendChild(el("label","meeting-request-label","Date"));var dateInput=document.createElement("input");dateInput.type="date";dateInput.className="meeting-request-input";dateInput.min=todayDateStr();dateField.appendChild(dateInput);row.appendChild(dateField);var timeField=el("div","meeting-request-datetime-field");timeField.appendChild(el("label","meeting-request-label","Time"));var timeInput=document.createElement("input");timeInput.type="time";timeInput.className="meeting-request-input";timeInput.step=1800;timeField.appendChild(timeInput);row.appendChild(timeField);form.appendChild(row);var defaults=defaultMeetingDateTime();dateInput.value=defaults.date;timeInput.value=defaults.time;var err=el("p","meeting-request-error hidden");form.appendChild(err);var actions=el("div","meeting-request-actions");var submitBtn=el("button","btn btn-primary meeting-request-submit","Send Request");submitBtn.type="submit";var cancelBtn=el("button","btn","Cancel");cancelBtn.type="button";cancelBtn.addEventListener("click",renderTrigger);actions.appendChild(submitBtn);actions.appendChild(cancelBtn);form.appendChild(actions);form.addEventListener("submit",function(e){e.preventDefault();var problem=validateDraft(purpose.value.trim(),dateInput.value,timeInput.value);if(problem){err.textContent=problem;err.classList.remove("hidden");return}err.classList.add("hidden");submitBtn.disabled=true;submitBtn.textContent="Sending…";var params=Object.assign({},ctx.params(),{purpose:purpose.value.trim(),notes:notes.value.trim(),requestedDate:dateInput.value,requestedTime:timeInput.value});Api.post("requestMeeting",params).then(function(res){submitBtn.disabled=false;submitBtn.textContent="Send Request";if(!res.ok){err.textContent=friendlyError(res);err.classList.remove("hidden");return}meetings.push(res.meeting);renderTrigger();render()})});return form}function actionButton(label,cls,disabled,onClick){var b=el("button","btn "+(cls||""),label);b.type="button";if(disabled)b.disabled=true;b.addEventListener("click",onClick);return b}function callAction(action,meetingId,extra){busyMeetingId=meetingId;render();var params=Object.assign({},ctx.params(),{meetingId:meetingId},extra||{});return Api.post(action,params).then(function(res){busyMeetingId=null;if(!res.ok){alert(friendlyError(res));render();return}if(res.meeting){var idx=meetings.findIndex(function(m){return m.meetingId===meetingId});if(idx!==-1)meetings[idx]=res.meeting;render()}else{refresh()}})}function renderCard(m){var card=el("div","meeting-card meeting-card--"+m.status.toLowerCase());var top=el("div","meeting-card-top");top.appendChild(el("span","meeting-card-purpose",m.purpose));top.appendChild(el("span","meeting-card-status",statusLabel(m)));card.appendChild(top);if(m.requestedDate)card.appendChild(el("p","meeting-card-when",fmtWhen(m.requestedDate,m.requestedTime)));if(m.notes)card.appendChild(el("p","meeting-card-notes",m.notes));var isBusy=busyMeetingId===m.meetingId;var isRecipient=m.recipientType===ctx.role;var actions=el("div","meeting-card-actions");if((m.status==="REQUESTED"||m.status==="RINGING")&&isRecipient){actions.appendChild(actionButton("Accept","btn-primary",isBusy,function(){callAction("respondToMeeting",m.meetingId,{accept:true})}));actions.appendChild(actionButton("Decline","",isBusy,function(){callAction("respondToMeeting",m.meetingId,{accept:false})}))}else if(m.status==="RINGING"){card.appendChild(el("p","meeting-card-hint","Calling…"+(m.ringingSecondsLeft!=null?" ("+m.ringingSecondsLeft+"s)":"")))}if(m.status==="MISSED"){card.appendChild(el("p","meeting-card-hint","No answer."));actions.appendChild(actionButton("Call Again","btn-primary",isBusy,startCallNow))}if(m.status==="ACCEPTED"&&m.meetFailed){card.appendChild(el("p","meeting-card-error","We couldn't set up the video call."));actions.appendChild(actionButton("Retry","btn-primary",isBusy,function(){callAction("retryMeetingSpace",m.meetingId)}))}else if(m.status==="ACCEPTED"){card.appendChild(el("p","meeting-card-hint","Setting up the video call…"))}if(m.status==="READY"&&m.meetingUrl&&/^https:\/\//.test(m.meetingUrl)){var join=el("a","btn btn-primary","Join Video Call");join.href=m.meetingUrl;join.target="_blank";join.rel="noopener";actions.appendChild(join);actions.appendChild(actionButton("End Meeting","",isBusy,function(){if(confirm("End this meeting?"))callAction("endMeeting",m.meetingId)}))}if(m.status==="REQUESTED"||m.status==="ACCEPTED"||m.status==="READY"||m.status==="RINGING"&&!isRecipient){actions.appendChild(actionButton("Cancel Meeting","btn-danger",isBusy,function(){if(confirm("Cancel this meeting?"))callAction("cancelMeeting",m.meetingId)}))}if(actions.children.length)card.appendChild(actions);return card}function render(){list.innerHTML="";if(meetings.length===0){list.appendChild(el("p","meeting-empty-state","No meetings yet."))}else{meetings.slice().reverse().forEach(function(m){list.appendChild(renderCard(m))})}if(!formWrap.querySelector(".meeting-request-form"))renderTrigger();scheduleRingPollIfNeeded()}var ringPollTimer=null;function hasPendingRing(){return meetings.some(function(m){return m.status==="RINGING"})}function scheduleRingPollIfNeeded(){if(ringPollTimer||!hasPendingRing())return;ringPollTimer=setTimeout(function(){ringPollTimer=null;refresh()},3e3)}function stopRingPolling(){if(ringPollTimer){clearTimeout(ringPollTimer);ringPollTimer=null}}function refresh(){return Api.post("listMeetingsForConversation",ctx.params()).then(function(res){if(!res.ok){list.innerHTML="";list.appendChild(el("p","meeting-empty-state","Couldn't load meetings. Please try again."));return}meetings=res.meetings||[];render()})}renderTrigger();refresh();return{stop:stopRingPolling}}window.MwaketeMeetings={mount:mount}})();